import { type ReactElement } from "react";
import { Navigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useAdminAccess } from "../hooks/useAdminAccess";

export function RequireAdmin({ children }: { children: ReactElement }) {
  const { user, loading: authLoading } = useAuth();
  const { loading: accessLoading, isAdmin } = useAdminAccess();

  if (authLoading || accessLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-bg-primary">
        <div
          className="h-9 w-9 animate-spin rounded-full border-2 border-brand-gold/30 border-t-brand-gold"
          aria-hidden
        />
        <span className="sr-only">Chargement</span>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/auth" replace />;
  }

  if (!isAdmin) {
    return <Navigate to="/" replace />;
  }

  return children;
}

import { type ReactElement, useEffect, useState } from "react";
import { Navigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useAdminAccess } from "../hooks/useAdminAccess";

// RequireAdmin: protects admin routes but tolerates short transient auth
// glitches. If the user becomes briefly unauthenticated (e.g., token
// refresh), we wait a short grace period before redirecting to /auth to
// avoid losing in-progress edits due to a transient null session.
export function RequireAdmin({ children }: { children: ReactElement }) {
  const { user, loading: authLoading } = useAuth();
  const { loading: accessLoading, isAdmin } = useAdminAccess();
  const [graceExpired, setGraceExpired] = useState(false);

  useEffect(() => {
    // Reset grace when auth state is loading or user present
    if (authLoading || user) {
      setGraceExpired(false);
      return;
    }

    // Start grace timer when user is null and not loading
    const t = setTimeout(() => setGraceExpired(true), 2500);
    return () => clearTimeout(t);
  }, [authLoading, user]);

  if (authLoading || accessLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-bg-primary">
        <div
          className="h-9 w-9 animate-spin rounded-full border-2 border-brand-gold/30 border-t-brand-gold"
          aria-hidden
        />
        <span className="sr-only">Chargement</span>
      </div>
    );
  }

  // If user is missing but grace period not expired yet, show spinner and
  // allow time for auth to stabilize (prevents instant redirect on brief
  // auth flickers).
  if (!user && !graceExpired) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-bg-primary">
        <div
          className="h-9 w-9 animate-spin rounded-full border-2 border-brand-gold/30 border-t-brand-gold"
          aria-hidden
        />
        <span className="sr-only">Vérification de session…</span>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/auth" replace />;
  }

  if (!isAdmin) {
    return <Navigate to="/" replace />;
  }

  return children;
}

import { createContext, useContext, useState, useEffect, useCallback, useMemo, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
import type { User, Session } from '@supabase/supabase-js';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: string | null }>;
  signIn: (email: string, password: string) => Promise<{ error: string | null }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for auth changes (login, logout, token refresh)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  const signUp = useCallback(async (email: string, password: string, fullName: string) => {
    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { full_name: fullName },
      },
    });
    if (error) return { error: error.message };
    return { error: null };
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) return { error: error.message };
    return { error: null };
  }, []);

  const signOut = useCallback(async () => {
    await supabase.auth.signOut();
    setUser(null);
    setSession(null);
  }, []);

  const value = useMemo(
    () => ({ user, session, loading, signUp, signIn, signOut }),
    [user, session, loading, signUp, signIn, signOut],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { createContext, useContext, useState, useEffect, useCallback, useMemo, ReactNode } from 'react';
import { supabase } from '../lib/supabase';
import type { User, Session } from '@supabase/supabase-js';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: string | null }>;
  signIn: (email: string, password: string) => Promise<{ error: string | null }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (process.env.NODE_ENV !== 'production') {
        // eslint-disable-next-line no-console
        console.debug('[Auth] initial session', session);
      }
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for auth changes (login, logout, token refresh)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        if (process.env.NODE_ENV !== 'production') {
          // eslint-disable-next-line no-console
          console.debug('[Auth] onAuthStateChange', event, session);
        }
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  const signUp = useCallback(async (email: string, password: string, fullName: string) => {
    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { full_name: fullName },
      },
    });
    if (error) return { error: error.message };
    return { error: null };
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) return { error: error.message };
    return { error: null };
  }, []);

  const signOut = useCallback(async () => {
    await supabase.auth.signOut();
    setUser(null);
    setSession(null);
  }, []);

  const value = useMemo(
    () => ({ user, session, loading, signUp, signIn, signOut }),
    [user, session, loading, signUp, signIn, signOut],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { useEffect, useState } from "react";
import { supabase } from "../lib/supabase";
import { useAuth } from "../context/AuthContext";
import { normalizeProfileRole } from "../components/admin/adminShared";

/**
 * Rôle admin = ligne `profiles.role` normalisée en « admin » (voir UserManager).
 */
export function useAdminAccess() {
  const { user, loading: authLoading } = useAuth();
  const [resolved, setResolved] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    if (authLoading) return;

    if (!user) {
      setIsAdmin(false);
      setResolved(true);
      return;
    }

    setResolved(false);
    let cancelled = false;

    void supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .maybeSingle()
      .then(({ data, error }) => {
        if (cancelled) return;
        if (error || data?.role == null) {
          setIsAdmin(false);
        } else {
          setIsAdmin(normalizeProfileRole(String(data.role)) === "admin");
        }
        setResolved(true);
      });

    return () => {
      cancelled = true;
    };
  }, [user, authLoading]);

  const loading = authLoading || (user != null && !resolved);

  return { loading, isAdmin };
}

import { useEffect, useState } from "react";
import { supabase } from "../lib/supabase";
import { useAuth } from "../context/AuthContext";
import { normalizeProfileRole } from "../components/admin/adminShared";

// Shared in-memory cache to avoid repeated role lookups for the same user
// across multiple components/hooks mounts.
const adminRoleCache = new Map<string, boolean>();
const adminRoleInflight = new Map<string, Promise<boolean>>();

async function fetchAdminRole(userId: string): Promise<boolean> {
  const cached = adminRoleCache.get(userId);
  if (cached != null) return cached;

  const inflight = adminRoleInflight.get(userId);
  if (inflight) return inflight;

  const request = (async () => {
    try {
      const { data, error } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", userId)
        .maybeSingle();

      const isAdmin = !error && data?.role != null && normalizeProfileRole(String(data.role)) === "admin";
      adminRoleCache.set(userId, isAdmin);
      return isAdmin;
    } catch {
      return false;
    } finally {
      adminRoleInflight.delete(userId);
    }
  })();

  adminRoleInflight.set(userId, request);
  return request;
}

/**
 * Rôle admin = ligne `profiles.role` normalisée en « admin » (voir UserManager).
 */
export function useAdminAccess() {
  const { user, loading: authLoading } = useAuth();
  const [resolved, setResolved] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const userId = user?.id ?? null;

  useEffect(() => {
    if (authLoading) return;

    if (!userId) {
      setIsAdmin(false);
      setResolved(true);
      return;
    }

    const cached = adminRoleCache.get(userId);
    if (cached != null) {
      setIsAdmin(cached);
      setResolved(true);
      return;
    }

    setResolved(false);
    let cancelled = false;

    void fetchAdminRole(userId).then((nextIsAdmin) => {
        if (cancelled) return;
        setIsAdmin(nextIsAdmin);
        setResolved(true);
      });

    return () => {
      cancelled = true;
    };
  }, [userId, authLoading]);

  const loading = authLoading || (userId != null && !resolved);

  return { loading, isAdmin };
}

import { useEffect, useState } from "react";
import { Outlet, Link, useLocation } from "react-router-dom";
import {
  LayoutDashboard,
  Settings,
  LogOut,
  FileText,
  ShoppingBag,
  Users,
  Heart,
  Mail,
  PenTool,
  Calendar,
  Menu,
  X,
  ExternalLink,
  MapPin,
  Info,
} from "lucide-react";
import { cn } from "../../lib/utils";

const navItems = [
  { path: "/admin", label: "Vue d’ensemble", icon: LayoutDashboard, end: true },
  { path: "/admin/reservations", label: "Réservations", icon: Calendar, end: false },
  { path: "/admin/boutique", label: "Boutique", icon: ShoppingBag, end: false },
  { path: "/admin/experience-client", label: "Expérience client", icon: Heart, end: false },
  { path: "/admin/content", label: "Pays & offres", icon: FileText, end: false },
  { path: "/admin/signature", label: "Signature & éditorial", icon: PenTool, end: false },
  { path: "/admin/points-of-interest", label: "Carte & Localités", icon: MapPin, end: false },
  { path: "/admin/newsletter", label: "Newsletter", icon: Mail, end: false },
  { path: "/admin/users", label: "Utilisateurs", icon: Users, end: false },
  { path: "/admin/settings", label: "Configuration", icon: Settings, end: false },
  { path: "/admin/settings/about", label: "About Us", icon: Info, end: false },
] as const;

function isNavActive(path: string, item: (typeof navItems)[number]) {
  return item.end ? path === item.path : path === item.path || path.startsWith(`${item.path}/`);
}

type SidebarNavProps = {
  currentPath: string;
  onNavigate?: () => void;
  /** ex. flex-grow sur la sidebar bureau */
  className?: string;
};

function SidebarBrand() {
  return (
    <div className="border-b border-border-primary/80 p-6 pl-[max(1.5rem,env(safe-area-inset-left))] md:p-8">
      <Link to="/admin" className="group block">
        <p className="text-[9px] tracking-[0.35em] font-black text-brand-gold/90 uppercase mb-1">Casa Privilege</p>
        <h1 className="font-serif text-xl md:text-2xl tracking-[0.2em] text-text-primary group-hover:text-brand-gold transition-colors">
          Console
        </h1>
      </Link>
    </div>
  );
}

function SidebarNav({ currentPath, onNavigate, className }: SidebarNavProps) {
  return (
    <nav
      className={cn(
        "flex flex-col gap-0.5 px-3 py-6 pl-[max(0.75rem,env(safe-area-inset-left))] md:pl-3",
        className
      )}
      aria-label="Navigation administration"
    >
      {navItems.map((item) => {
        const active = isNavActive(currentPath, item);
        return (
          <Link
            key={item.path}
            to={item.path}
            data-active={active ? "true" : "false"}
            aria-current={active ? "page" : undefined}
            onClick={onNavigate}
            className="admin-nav-link"
          >
            <item.icon size={19} strokeWidth={1.5} className="shrink-0 opacity-80" aria-hidden />
            <span>{item.label}</span>
          </Link>
        );
      })}
    </nav>
  );
}

function SidebarFooter({ onNavigate }: { onNavigate?: () => void }) {
  return (
    <div className="mt-auto space-y-1 border-t border-border-primary/80 p-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] pl-[max(0.75rem,env(safe-area-inset-left))] md:pb-3 md:pl-3">
      <Link
        to="/"
        onClick={onNavigate}
        className="admin-nav-link text-text-primary/50 hover:text-brand-gold"
      >
        <ExternalLink size={19} strokeWidth={1.5} aria-hidden />
        <span>Site public</span>
      </Link>
      <Link
        to="/"
        onClick={onNavigate}
        className="admin-nav-link text-text-primary/45 hover:text-text-primary"
      >
        <LogOut size={19} strokeWidth={1.5} aria-hidden />
        <span>Quitter l’admin</span>
      </Link>
    </div>
  );
}

export function AdminLayout() {
  const location = useLocation();
  const path = location.pathname;
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    setMobileOpen(false);
  }, [path]);

  useEffect(() => {
    if (!mobileOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, [mobileOpen]);

  const closeMobile = () => setMobileOpen(false);

  return (
    <div className="min-h-[100dvh] min-h-screen bg-bg-primary text-text-primary flex flex-col md:flex-row font-sans">
      {/* Barre mobile — safe area encoche / status bar */}
      <header className="md:hidden sticky top-0 z-30 flex items-center justify-between gap-2 sm:gap-3 border-b border-border-primary bg-bg-primary/95 backdrop-blur-md pt-[max(0.5rem,env(safe-area-inset-top))] pb-2.5 pl-[max(0.75rem,env(safe-area-inset-left))] pr-[max(0.75rem,env(safe-area-inset-right))]">
        <button
          type="button"
          onClick={() => setMobileOpen(true)}
          className="flex min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 shrink-0 items-center justify-center rounded-xl border border-border-primary text-text-primary transition-colors hover:bg-text-primary/[0.08] active:bg-text-primary/[0.12] focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-gold touch-manipulation"
          aria-expanded={mobileOpen}
          aria-controls="admin-mobile-drawer"
        >
          <Menu size={22} strokeWidth={1.5} aria-hidden />
          <span className="sr-only">Ouvrir le menu</span>
        </button>
        <span className="min-w-0 truncate text-center text-[10px] sm:text-[12px] font-black uppercase tracking-[0.2em] sm:tracking-[0.25em] text-brand-gold">
          Console
        </span>
        <div className="min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 shrink-0" aria-hidden />
      </header>

      {/* Drawer mobile */}
      <div
        id="admin-mobile-drawer"
        className={cn(
          "fixed inset-0 z-50 md:hidden transition-opacity duration-300",
          mobileOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
        )}
        aria-hidden={!mobileOpen}
      >
        <button
          type="button"
          className="absolute inset-0 bg-black/50 backdrop-blur-[2px]"
          onClick={closeMobile}
          aria-label="Fermer le menu"
        />
        <aside
          className={cn(
            "admin-sidebar absolute bottom-0 left-0 top-0 flex max-h-[100dvh] min-h-0 w-[min(20.5rem,min(92vw,100%-2.5rem))] max-w-[calc(100vw-env(safe-area-inset-left)-0.5rem)] flex-col overflow-hidden border-r border-border-primary shadow-2xl transition-transform duration-300 ease-out",
            "pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]",
            mobileOpen ? "translate-x-0" : "-translate-x-full"
          )}
          aria-label="Menu administration"
        >
          <div className="flex shrink-0 items-center justify-end px-3 pt-2 pr-[max(0.75rem,env(safe-area-inset-right))]">
            <button
              type="button"
              onClick={closeMobile}
              className="flex min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 items-center justify-center rounded-xl border border-border-primary/80 transition-colors hover:bg-text-primary/[0.08] active:bg-text-primary/[0.12] focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-gold touch-manipulation"
              aria-label="Fermer le menu"
            >
              <X size={20} strokeWidth={1.5} />
            </button>
          </div>
          <div className="shrink-0">
            <SidebarBrand />
          </div>
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain py-1 [-webkit-overflow-scrolling:touch]">
            <SidebarNav currentPath={path} onNavigate={closeMobile} />
          </div>
          <div className="shrink-0">
            <SidebarFooter onNavigate={closeMobile} />
          </div>
        </aside>
      </div>

      {/* Sidebar bureau */}
      <aside
        className="admin-sidebar hidden md:flex w-64 xl:w-72 shrink-0 border-r border-border-primary flex-col sticky top-0 h-screen overflow-y-auto overscroll-contain"
        aria-label="Navigation administration"
      >
        <SidebarBrand />
        <SidebarNav currentPath={path} className="flex-grow" />
        <SidebarFooter />
      </aside>

      <main
        className="flex-grow min-w-0 min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-3.5 py-4 sm:px-6 sm:py-8 md:min-h-screen md:px-10 lg:px-12 lg:py-10 pb-[max(1.25rem,env(safe-area-inset-bottom))] pl-[max(0.9rem,env(safe-area-inset-left))] pr-[max(0.9rem,env(safe-area-inset-right))] bg-[radial-gradient(ellipse_85%_55%_at_50%_-18%,rgba(229,169,58,0.07),transparent)] dark:bg-[radial-gradient(ellipse_80%_45%_at_50%_-12%,rgba(229,169,58,0.09),transparent)]"
        id="admin-main"
      >
        <Outlet />
      </main>
    </div>
  );
}

