export function AdminLayout() {
  const location = useLocation();
  const path = location.pathname;
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    setMobileOpen(false);
  }, [path]);

  useEffect(() => {
    if (!mobileOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, [mobileOpen]);

  // Autosave admin form fields to sessionStorage to avoid data loss when
  // the user switches tabs or navigates away temporarily. We save inputs
  // (by name) under a key specific to the current admin path.
  useEffect(() => {
    const main = document.getElementById('admin-main');
    if (!main) return;
    const storageKey = `admin:draft:${path}`;

    // Restore saved values first
    try {
      const raw = sessionStorage.getItem(storageKey);
      if (raw) {
        const saved = JSON.parse(raw) as Record<string, any>;
        Object.keys(saved).forEach((name) => {
          const el = main.querySelector(`[name="${name}"]`) as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | null;
          if (!el) return;
          if (el instanceof HTMLInputElement && (el.type === 'checkbox' || el.type === 'radio')) {
            (el as HTMLInputElement).checked = Boolean(saved[name]);
          } else {
            (el as any).value = saved[name];
            // dispatch input event so React-controlled inputs update if needed
            try {
              el.dispatchEvent(new Event('input', { bubbles: true }));
              el.dispatchEvent(new Event('change', { bubbles: true }));
            } catch (e) {
              // ignore
            }
          }
        });
      }
    } catch (e) {
      // ignore JSON errors
    }

    let timer: ReturnType<typeof setTimeout> | null = null;
    const save = () => {
      try {
        const data: Record<string, any> = {};
        const inputs = main.querySelectorAll('input[name], textarea[name], select[name]');
        inputs.forEach((node) => {
          const name = (node as Element).getAttribute('name');
          if (!name) return;
          if (node instanceof HTMLInputElement && (node.type === 'checkbox' || node.type === 'radio')) {
            data[name] = node.checked;
          } else {
            data[name] = (node as HTMLInputElement).value;
          }
        });
        sessionStorage.setItem(storageKey, JSON.stringify(data));
      } catch (e) {
        // ignore
      }
    };

    const scheduleSave = () => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        save();
        timer = null;
      }, 300);
    };

    const onInput = (e: Event) => scheduleSave();
    const onChange = (e: Event) => scheduleSave();
    const onVisibility = () => {
      if (document.visibilityState === 'hidden') save();
    };

    main.addEventListener('input', onInput, { passive: true });
    main.addEventListener('change', onChange);
    window.addEventListener('pagehide', save);
    document.addEventListener('visibilitychange', onVisibility);

    return () => {
      if (timer) clearTimeout(timer as any);
      main.removeEventListener('input', onInput as any);
      main.removeEventListener('change', onChange as any);
      window.removeEventListener('pagehide', save);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [path]);

  const closeMobile = () => setMobileOpen(false);

  return (
    <div className="min-h-[100dvh] min-h-screen bg-bg-primary text-text-primary flex flex-col md:flex-row font-sans">
      {/* Barre mobile — safe area encoche / status bar */}
      <header className="md:hidden sticky top-0 z-30 flex items-center justify-between gap-2 sm:gap-3 border-b border-border-primary bg-bg-primary/95 backdrop-blur-md pt-[max(0.5rem,env(safe-area-inset-top))] pb-2.5 pl-[max(0.75rem,env(safe-area-inset-left))] pr-[max(0.75rem,env(safe-area-inset-right))]">
        <button
          type="button"
          onClick={() => setMobileOpen(true)}
          className="flex min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 shrink-0 items-center justify-center rounded-xl border border-border-primary text-text-primary transition-colors hover:bg-text-primary/[0.08] active:bg-text-primary/[0.12] focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-gold touch-manipulation"
          aria-expanded={mobileOpen}
          aria-controls="admin-mobile-drawer"
        >
          <Menu size={22} strokeWidth={1.5} aria-hidden />
          <span className="sr-only">Ouvrir le menu</span>
        </button>
        <span className="min-w-0 truncate text-center text-[10px] sm:text-[12px] font-black uppercase tracking-[0.2em] sm:tracking-[0.25em] text-brand-gold">
          Console
        </span>
        <div className="min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 shrink-0" aria-hidden />
      </header>

      {/* Drawer mobile */}
      <div
        id="admin-mobile-drawer"
        className={cn(
          "fixed inset-0 z-50 md:hidden transition-opacity duration-300",
          mobileOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
        )}
        aria-hidden={!mobileOpen}
      >
        <button
          type="button"
          className="absolute inset-0 bg-black/50 backdrop-blur-[2px]"
          onClick={closeMobile}
          aria-label="Fermer le menu"
        />
        <aside
          className={cn(
            "admin-sidebar absolute bottom-0 left-0 top-0 flex max-h-[100dvh] min-h-0 w-[min(20.5rem,min(92vw,100%-2.5rem))] max-w-[calc(100vw-env(safe-area-inset-left)-0.5rem)] flex-col overflow-hidden border-r border-border-primary shadow-2xl transition-transform duration-300 ease-out",
            "pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]",
            mobileOpen ? "translate-x-0" : "-translate-x-full"
          )}
          aria-label="Menu administration"
        >
          <div className="flex shrink-0 items-center justify-end px-3 pt-2 pr-[max(0.75rem,env(safe-area-inset-right))]">
            <button
              type="button"
              onClick={closeMobile}
              className="flex min-h-12 min-w-12 sm:min-h-11 sm:min-w-11 items-center justify-center rounded-xl border border-border-primary/80 transition-colors hover:bg-text-primary/[0.08] active:bg-text-primary/[0.12] focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-gold touch-manipulation"
              aria-label="Fermer le menu"
            >
              <X size={20} strokeWidth={1.5} />
            </button>
          </div>
          <div className="shrink-0">
            <SidebarBrand />
          </div>
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain py-1 [-webkit-overflow-scrolling:touch]">
            <SidebarNav currentPath={path} onNavigate={closeMobile} />
          </div>
          <div className="shrink-0">
            <SidebarFooter onNavigate={closeMobile} />
          </div>
        </aside>
      </div>

      {/* Sidebar bureau */}
      <aside
        className="admin-sidebar hidden md:flex w-64 xl:w-72 shrink-0 border-r border-border-primary flex-col sticky top-0 h-screen overflow-y-auto overscroll-contain"
        aria-label="Navigation administration"
      >
        <SidebarBrand />
        <SidebarNav currentPath={path} className="flex-grow" />
        <SidebarFooter />
      </aside>

      <main
        className="flex-grow min-w-0 min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-3.5 py-4 sm:px-6 sm:py-8 md:min-h-screen md:px-10 lg:px-12 lg:py-10 pb-[max(1.25rem,env(safe-area-inset-bottom))] pl-[max(0.9rem,env(safe-area-inset-left))] pr-[max(0.9rem,env(safe-area-inset-right))] bg-[radial-gradient(ellipse_85%_55%_at_50%_-18%,rgba(229,169,58,0.07),transparent)] dark:bg-[radial-gradient(ellipse_80%_45%_at_50%_-12%,rgba(229,169,58,0.09),transparent)]"
        id="admin-main"
      >
        <Outlet />
      </main>
    </div>
  );
}
